def scarf_back(sh, T=lambda p: p):
    """inside of the cowl behind the neck"""
    P = T(spl(np.array([(1066, 640), (1090, 560), (1180, 520), (1330, 500), (1470, 506), (1560, 560), (1604, 640), (1500, 720), (1280, 760), (1120, 720)]), True, (1, 5), n=9)); sh.put(P, SCARF); sh.k.fill(P, BLACK)
    for k, L in enumerate([[(1560, 566), (1500, 596), (1452, 660)], [(1590, 620), (1540, 640), (1490, 690)], [(1096, 566), (1140, 600), (1168, 650)]]): brush(sh.g, T(spl(np.array(L), n=8)), [.2, 2.2, .2], '#6b6570', k, .4)


SC = dict(
    right=([(1462, 520), (1520, 528), (1578, 566), (1612, 622), (1618, 690), (1580, 748), (1500, 790), (1400, 806), (1430, 730), (1462, 660), (1470, 590)], (0, 3, 5, 7)),
    upper=([(1084, 566), (1066, 610), (1072, 660), (1120, 712), (1210, 748), (1320, 752), (1420, 720), (1486, 660), (1480, 610), (1462, 560), (1420, 610), (1350, 652), (1262, 664), (1180, 640), (1126, 600)], (0, 3, 7, 9, 13)),
    lower=([(1066, 640), (1040, 690), (1046, 742), (1098, 800), (1180, 846), (1290, 866), (1400, 852), (1500, 812), (1590, 742), (1610, 690), (1540, 716), (1440, 762), (1330, 782), (1220, 772), (1126, 726)], (0, 3, 8, 9, 14)))


def scarf_front(sh, T0=lambda p: p, seed=5, k=.90):
    """three overlapping wraps of heavy dark cloth"""
    T = lambda p: T0((np.asarray(p, float) - (1330, 700)) * (k, .97) + (1330, 700))
    bk = T(spl(np.array([(1084, 600), (1060, 700), (1110, 800), (1290, 850), (1500, 800), (1600, 700), (1560, 600), (1462, 540), (1420, 640), (1262, 672), (1150, 640)]), True, n=8)); sh.put(bk, SCARF); sh.k.fill(bk, BLACK)
    O = lambda L, n=8: T(spl(np.array(L, float), n=n)); S = lambda L, c=(), n=8: T(spl(np.array(L, float), True, c, n))
    def wrap(name, lights, blacks, creases, scr):
        P = S(*SC[name]); sh.put(P, SCARF); sh.clip(P)
        for L, c in lights: sh.a.fill(S(L, c), SCARF_L); sh.wash(S(L, c), '#8d8794', .35)
        for L, c in blacks: sh.k.fill(S(L, c), BLACK)
        for k, (L, w, f, sp, sd_) in enumerate(creases): crease(sh, np.array(O(L)), w, f, sp, sd_, seed + k * 3 + len(name), hw=3.4, t1=(.55, .98))
        for k, L in enumerate(scr):
            q = O(L)
            for j in range(4): brush(sh.g, off(q, 4.5 * j + 1.)[int(len(q) * .06 * j):int(len(q) * (1 - .10 * j))], [.2, 1.9 - .3 * j, 1.2, .2], '#a9a29c' if j < 2 else '#777280', seed + k * 7 + j, .5)
        sh.unclip(); c = SC[name][0]; edge(sh, T(np.array(c + c[:1])), [3.5, 6, 5, 6.5, 5, 6, 5, 4, 5, 3.5], seed + 60 + len(name), corners=SC[name][1])
    wrap('right', [([(1500, 548), (1560, 580), (1594, 640), (1590, 700), (1552, 660), (1520, 600)], (0, 3)), ([(1452, 742), (1520, 716), (1580, 706), (1540, 750), (1470, 786)], (0, 2))],
         [([(1462, 520), (1500, 600), (1512, 680), (1480, 740), (1400, 806), (1430, 730), (1462, 660)], (0, 4)), ([(1618, 640), (1612, 700), (1570, 752), (1500, 790), (1560, 740), (1596, 690)], (0, 3))],
         [([(1500, 540), (1546, 610), (1556, 690), (1524, 760)], 10, 7, 34, 1), ([(1590, 600), (1586, 660), (1548, 720)], 8, 5, 22, 1)], [[(1526, 560), (1570, 600), (1586, 650)], [(1470, 766), (1530, 740), (1570, 716)]])
    wrap('lower', [([(1072, 690), (1096, 748), (1180, 806), (1280, 826), (1230, 796), (1140, 750), (1100, 700)], (0, 3)), ([(1330, 832), (1440, 806), (1540, 748), (1592, 704), (1530, 738), (1430, 782), (1340, 800)], (0, 3))],
         [([(1126, 726), (1220, 772), (1330, 782), (1440, 762), (1540, 716), (1600, 692), (1520, 752), (1420, 790), (1310, 806), (1200, 796), (1120, 752)], (0, 5)), ([(1046, 742), (1098, 790), (1180, 832), (1290, 848), (1400, 836), (1500, 800), (1590, 740), (1500, 820), (1290, 880), (1090, 810)], (0, 6))],
         [([(1090, 700), (1120, 752), (1200, 806), (1290, 830)], 9, 8, 30, -1), ([(1600, 700), (1530, 762), (1430, 808), (1330, 826)], 10, 8, 32, 1), ([(1180, 770), (1240, 796), (1330, 806)], 7, 5, 22, -1)], [[(1104, 760), (1176, 808), (1260, 832)], [(1360, 828), (1450, 800), (1536, 748)]])
    wrap('upper', [([(1090, 600), (1100, 650), (1160, 700), (1240, 722), (1190, 690), (1130, 648), (1106, 610)], (0, 3)), ([(1330, 716), (1420, 690), (1468, 640), (1462, 600), (1420, 650), (1346, 690)], (0, 3))],
         [([(1126, 600), (1180, 640), (1262, 664), (1350, 652), (1420, 610), (1462, 566), (1440, 636), (1360, 682), (1262, 694), (1170, 666)], (0, 5)), ([(1072, 660), (1120, 702), (1210, 736), (1320, 740), (1420, 708), (1486, 655), (1420, 735), (1310, 770), (1180, 752), (1080, 690)], (0, 5))],
         [([(1092, 584), (1116, 640), (1180, 694), (1262, 720)], 8, 7, 26, -1), ([(1470, 590), (1440, 650), (1370, 700), (1300, 716)], 9, 8, 30, 1), ([(1200, 676), (1270, 694), (1350, 684)], 6, 4, 18, -1)], [[(1106, 636), (1160, 688), (1230, 716)], [(1376, 704), (1440, 664), (1464, 618)]])


class Prayer:
    """kneeling prayer, camera slightly below, turned to picture left.  All shapes in design px."""
    NEAR_LIP = [(1478, 962), (1434, 984), (1394, 1016), (1366, 1056), (1352, 1110)]; FAR_LIP = [(1012, 948), (1036, 990), (1076, 1026), (1112, 1056), (1122, 1110)]

    def __init__(self, T=None, seed=11): self.T = T or (lambda p: np.asarray(p, float)); self.seed = seed

    def robe(self, sh):
        """torso: collar, black inner robe"""
        T = self.T; sd = self.seed; S = lambda L, c=(), n=9: T(spl(np.array(L, float), True, c, n)); O = lambda L, n=10: T(spl(np.array(L, float), n=n))
        P = S([(1096, 742), (1010, 776), (960, 900), (960, 1110), (1780, 1110), (1780, 900), (1660, 770), (1540, 740)], (0, 3, 4, 7)); sh.put(P, CLOTH); sh.clip(P)
        sh.k.fill(S([(1150, 800), (1300, 830), (1440, 800), (1392, 900), (1330, 1010), (1300, 1110), (1080, 1110), (1120, 960), (1136, 880)], (0, 2, 5, 6)), BLACK)
        for k, L in enumerate([[(1250, 860), (1240, 960), (1210, 1100)], [(1276, 866), (1270, 950), (1250, 1080)], [(1330, 850), (1300, 930), (1276, 1010)]]): brush(sh.g, O(L), [.2, 2., .2], '#5b5560', k, .4)
        # right collar, wide white band
        C = [(1410, 806), (1500, 806), (1440, 900), (1384, 990), (1350, 1110), (1262, 1110), (1306, 1000), (1362, 900)]; sh.put(S(C, (0, 1, 4, 5)), CLOTH); sh.clip(S(C, (0, 1, 4, 5)))
        sh.wash(S([(1410, 806), (1448, 806), (1400, 890), (1340, 1000), (1308, 1110), (1262, 1110), (1306, 1000), (1362, 900)], (0, 1, 4, 5)), CLOTH_S, .9)
        crease(sh, O([(1470, 812), (1420, 890), (1360, 1000)]), 7, 6, 30, 1, sd + 5, hw=2.6); sh.unclip()
        edge(sh, O([(1410, 808), (1362, 900), (1306, 1000), (1262, 1110)]), [3, 6, 7, 5], sd + 1); edge(sh, O([(1500, 808), (1440, 900), (1384, 992), (1350, 1110)]), [2, 5, 6, 4], sd + 2)
        # shadow of torso behind the near sleeve
        sh.k.fill(S([(1500, 830), (1540, 880), (1520, 980), (1440, 1110), (1350, 1110), (1400, 1000), (1460, 900)], (0, 2, 4)), BLACK)
        sh.unclip()

    def poly(self, name):
        T = self.T
        if name == 'far': L = [(1100, 752), (1046, 762), (996, 796), (962, 870), (944, 950), (918, 1030), (900, 1110)] + self.FAR_LIP[::-1] + [(1040, 880), (1092, 820)]; c = (0, 2, 6, 7, 11)
        else: L = [(1540, 742), (1610, 758), (1672, 776), (1722, 812), (1760, 872), (1802, 934), (1830, 1010), (1846, 1110)] + self.NEAR_LIP[::-1] + [(1510, 900), (1532, 820)]; c = (0, 3, 7, 8, 12)
        return T(spl(np.array(L, float), True, c, 9))

    def insides(self, sh):
        S = lambda L, c=(), n=9: self.T(spl(np.array(L, float), True, c, n))
        sh.k.fill(S([(1012, 948), (1060, 920), (1150, 960), (1200, 1110), (1100, 1110), (1080, 1040)], (0, 3, 4)), BLACK); sh.k.fill(S([(1478, 962), (1440, 930), (1360, 930), (1280, 1000), (1250, 1110), (1370, 1110), (1400, 1030)], (0, 4, 5)), BLACK)

    def behind_lips(self):
        """screen regions a forearm must not cross (everything outside the sleeve mouths)"""
        T = self.T; O = lambda L: spl(np.array(L, float), n=8)
        return [T(np.vstack([O(self.NEAR_LIP), [(1352, 1200), (2100, 1200), (2100, 880), (1500, 940)]])), T(np.vstack([O(self.FAR_LIP), [(1122, 1200), (600, 1200), (600, 930)]]))]

    def scarf_shadow(self, sh):
        T = self.T; O = lambda L, n=8: T(spl(np.array(L, float), n=n)); A = [(1086, 780), (1150, 836), (1280, 866), (1400, 856), (1500, 818), (1590, 760)]; Bc = [(1060, 806), (1130, 872), (1276, 908), (1410, 896), (1524, 850), (1622, 782)]
        sh.wash(np.vstack([O(A), O([(x, y + 34) for x, y in Bc])[::-1]]), CLOTH_D, .9); sh.k.fill(np.vstack([O([(x, y - 30) for x, y in A]), O(A)[::-1]]), BLACK)
        feather(sh.k, O(A), O(Bc), 6., 4., seed=self.seed + 90, reach=(.3, 1.1), group=6, hole=.6, skew=.02, back=.3)

    def sleeves(self, sh):
        T = self.T; sd = self.seed; S = lambda L, c=(), n=9: T(spl(np.array(L, float), True, c, n)); O = lambda L, n=10: T(spl(np.array(L, float), n=n))
        # ------------------------------------------------ far sleeve: folds hang from the shoulder corner and gather at the mouth
        P = self.poly('far'); sh.put(P, CLOTH); sh.clip(P)
        sh.wash(S([(1100, 752), (1064, 800), (1036, 880), (1012, 950), (1040, 996), (1122, 1060), (1122, 1110), (1060, 1110), (1030, 1040), (990, 985), (986, 940), (1010, 860), (1046, 800)], (0, 3, 5, 6, 10)), CLOTH_S, .95)
        sh.wash(S([(1092, 820), (1064, 860), (1030, 930), (1012, 950), (1040, 880)], (0, 3)), CLOTH_D, .8)
        crease(sh, O([(1014, 948), (1004, 900), (1010, 850), (1030, 802)]), 11, 8, 26, -1, sd + 10, hw=3., t1=(.5, .95))
        crease(sh, O([(1012, 952), (972, 966), (944, 1000), (926, 1050)]), 13, 8, 30, 1, sd + 12, hw=3.2, t1=(.4, .9))
        crease(sh, O([(1034, 990), (1000, 1010), (968, 1054), (956, 1110)]), 12, 8, 34, 1, sd + 14, hw=3.2, t1=(.4, .95))
        crease(sh, O([(1078, 1030), (1058, 1064), (1050, 1110)]), 9, 6, 24, 1, sd + 18, hw=2.8)
        crease(sh, O([(1088, 790), (1062, 836), (1036, 890)]), 10, 6, 22, 1, sd + 16, hw=2.8)
        sh.unclip()
        # ------------------------------------------------ near sleeve: long pipe folds hook from the shoulder round the arm into the crook of the elbow
        P = self.poly('near'); sh.put(P, CLOTH); sh.clip(P)
        sh.wash(S([(1478, 962), (1394, 1016), (1352, 1110), (1500, 1110), (1560, 1076), (1660, 1040), (1720, 980), (1640, 1010), (1560, 1010), (1510, 990)], (0, 2, 3, 6, 9)), CLOTH_S, .95)
        sh.wash(S([(1510, 900), (1532, 820), (1540, 744), (1562, 800), (1568, 870), (1560, 920), (1600, 930), (1640, 900), (1610, 950), (1550, 985), (1480, 964)], (0, 2, 7, 10)), CLOTH_D, .80)
        sh.wash(S([(1850, 1110), (1832, 1010), (1800, 940), (1790, 1010), (1750, 1060), (1690, 1110)], (0, 2, 5)), CLOTH_S, .95); sh.wash(S([(1850, 1110), (1836, 1030), (1822, 1070), (1790, 1110)], (0, 1, 3)), CLOTH_D, .7)
        pool(sh, O([(1540, 744), (1554, 800), (1552, 870), (1528, 936), (1484, 964), (1516, 900), (1532, 826)]), (0, 4), sd + 30)
        crease(sh, O([(1486, 964), (1530, 930), (1560, 880), (1572, 810), (1580, 764)]), 16, 9, 34, -1, sd + 31, hw=3.4, t1=(.5, .98))
        crease(sh, O([(1484, 966), (1570, 950), (1640, 900), (1690, 830), (1704, 800)]), 18, 10, 40, -1, sd + 32, hw=3.6, t1=(.4, .9))
        crease(sh, O([(1480, 970), (1580, 1000), (1680, 972), (1750, 900), (1764, 874)]), 16, 10, 44, -1, sd + 36, hw=3.6, t1=(.4, .9))
        crease(sh, O([(1410, 1004), (1520, 1030), (1640, 1040), (1740, 990), (1806, 944)]), 17, 10, 46, -1, sd + 38, hw=3.6, t1=(.35, .85))
        crease(sh, O([(1372, 1050), (1450, 1066), (1540, 1090), (1600, 1130)]), 14, 9, 40, 1, sd + 39, hw=3.4, t1=(.4, .95))
        crease(sh, O([(1832, 1024), (1770, 1040), (1720, 1076), (1690, 1120)]), 12, 8, 30, 1, sd + 40, hw=3.2, t1=(.4, .9))
        # shoulder seam
        edge(sh, O([(1650, 772), (1664, 800), (1660, 836), (1646, 868)]), [.5, 2.6, 2.2, .3], sd + 45); edge(sh, O([(1656, 772), (1671, 800), (1668, 830)]), [.4, 1.4, .2], sd + 46)
        sh.unclip()
        edge(sh, O([(1100, 752), (1046, 762), (996, 796)]), [2, 5, 7], sd + 50); edge(sh, O([(996, 794), (962, 870), (944, 950), (918, 1030), (900, 1110)]), [4, 7, 6, 8, 6], sd + 51)
        edge(sh, O([(1540, 742), (1610, 758), (1672, 776), (1722, 812)]), [2, 5, 6, 8], sd + 52); edge(sh, O([(1720, 808), (1760, 872), (1802, 934), (1830, 1010), (1846, 1110)]), [4, 8, 7, 9, 7], sd + 53)
        for L, q in ((self.NEAR_LIP, 1), (self.FAR_LIP, -1)):
            edge(sh, O(L), [3, 7, 6, 7, 5], sd + 54 + q); edge(sh, off(O(L), -13 * q)[4:-2], [.5, 2.4, 2., 2.4, 1], sd + 57 + q)
